function gallery(project, name) {
  const images=project.images;
  return `<div class="project-gallery" data-gallery role="region" aria-roledescription="${t('carrusel','carousel')}" aria-label="${esc(t('Galería de ','Gallery of ')+name)}" tabindex="0"><div class="gallery-topbar"><div><span class="eyebrow">${t('UNA MIRADA MÁS CERCA','A CLOSER LOOK')}</span><h2>${t('Espacios & detalles','Spaces & details')}</h2></div><div class="gallery-tools"><button type="button" data-gallery-play aria-pressed="false">${t('Reproducir','Play')}</button><button type="button" data-gallery-expand>${t('Ampliar','Expand')}</button></div></div><div class="gallery-stage" data-gallery-stage>${images.map((filename,i)=>`<figure class="gallery-slide" data-slide role="group" aria-roledescription="${t('diapositiva','slide')}" aria-label="${i+1} ${t('de','of')} ${images.length}">${image(filename,t(`Vista ${i+1} de ${name}`,`View ${i+1} of ${name}`),{eager:i===0,sizes:'(max-width: 700px) 100vw, 90vw'})}<figcaption><span class="photo-kind">${visuals.photos[filename]?t('IMAGEN DE REFERENCIA','REFERENCE IMAGE'):t('PORTAFOLIO PROJECTCONS','PROJECTCONS PORTFOLIO')}</span><span>${credit(filename)}</span></figcaption></figure>`).join('')}<div class="gallery-arrows"><button type="button" data-gallery-prev aria-label="${t('Foto anterior','Previous photo')}">←</button><button type="button" data-gallery-next aria-label="${t('Foto siguiente','Next photo')}">→</button></div></div><div class="gallery-footer"><p>${t('Explora los espacios. Descubre los detalles.','Explore the spaces. Discover the details.')}</p><span data-gallery-status aria-live="polite" aria-atomic="true">01 / ${String(images.length).padStart(2,'0')}</span></div><div class="gallery-position" data-gallery-progress style="--position:20%"><span></span></div><div class="gallery-thumbs" data-gallery-strip aria-label="${t('Seleccionar fotografía','Choose a photo')}">${images.map((filename,i)=>`<button type="button" data-thumb aria-label="${t('Ver fotografía','View photo')} ${i+1}" aria-pressed="${i===0}">${image(filename,'',{decorative:true,sizes:'120px'})}<span>${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div><p class="gallery-hint">${t('Usa las flechas, el teclado o desliza para explorar. Reproducción automática opcional.','Use the arrows, keyboard or swipe to explore. Autoplay is optional.')}</p></div>`;
}
function detail(cat,project,i) {
  const name=projectName(project,i);
  const own=cat.projects[i]?.images.length;
  const previous=i>0?`<a href="proyecto-${String(i).padStart(2,'0')}.html">← ${t('Anterior','Previous')}</a>`:'<span></span>';
  const next=i<cat.count-1?`<a href="proyecto-${String(i+2).padStart(2,'0')}.html">${t('Siguiente','Next')} →</a>`:'<span></span>';
  return `<section class="detail-intro section"><div class="container">${crumbs([{text:t('Proyectos','Projects'),href:route('proyectos.html')},{text:catName(cat),href:'index.html'},{text:name}])}<div class="section-heading"><div><p class="eyebrow">${catName(cat)} / ${String(i+1).padStart(2,'0')}</p><h1>${esc(name)}</h1></div><div><span class="status-label">${t('EN DOCUMENTACIÓN','BEING DOCUMENTED')}</span><p>${own?t('Una mirada al material de este proyecto. Estamos preparando su historia y ficha completa.','A look at this project’s photography. We are preparing its full story and details.'):t('Estamos preparando este espacio. Mientras tanto, explora una selección de referencias visuales de esta categoría.','We are preparing this project page. In the meantime, explore a selection of visual references for this category.')}</p></div></div></div></section><section class="detail-section"><div class="container">${gallery(project,name)}<aside class="reference-note"><span aria-hidden="true">ⓘ</span><p><strong>${t('Imágenes ilustrativas de terceros.','Third-party illustrative images.')}</strong> ${t('Las fotos marcadas como referencia no son obras de PROJECTCONS y se sustituirán por material del proyecto. Las referencias de vivienda no representan desarrollos avalados por INFONAVIT.','Photos marked as references are not PROJECTCONS work and will be replaced with project photography. Housing references do not represent INFONAVIT-endorsed developments.')}</p></aside><nav class="project-pagination" aria-label="${t('Más proyectos','More projects')}">${previous}<a href="index.html">${t('Volver a la colección','Back to the collection')}</a>${next}</nav></div></section>`+cta(cat,name);
}
function privacy() {
  return `<section class="section legal-page"><div class="container prose">${crumbs([{text:t('Privacidad','Privacy')}])}<p class="eyebrow">PROJECTCONS</p><h1>${t('Tus datos,<br>con claridad.','Your data,<br>clearly explained.')}</h1><p class="lead">${t('Información sobre el formulario de contacto de esta vista previa.','Information about the contact form in this preview.')}</p><h2>${t('Qué datos se usan','What information is used')}</h2><p>${t('El formulario utiliza tu nombre, teléfono y los datos del proyecto que decidas compartir para preparar una consulta dirigida a PROJECTCONS. No pide documentos de identidad, datos bancarios ni archivos.','The form uses your name, phone number and project details you choose to provide to prepare an enquiry for PROJECTCONS. It does not request identity documents, bank details or file uploads.')}</p><h2>${t('Cuándo se comparten','When information is shared')}</h2><p>${t('El resumen se prepara en tu navegador. No se guarda en una base de datos de este sitio ni se envía automáticamente. Solo al pulsar «Abrir WhatsApp» se transfiere el texto a ese servicio; tú confirmas el envío dentro del chat. WhatsApp se rige por su propia política de privacidad.','The summary is prepared in your browser. It is not stored in a website database or sent automatically. Clicking “Open WhatsApp” transfers the text to that service; you confirm sending it in the chat. WhatsApp has its own privacy policy.')}</p><h2>${t('Contacto y seguimiento','Contact and follow-up')}</h2><p>${t('PROJECTCONS recibirá únicamente lo que envíes por WhatsApp para atender tu consulta y conversar sobre tu proyecto. Para solicitar aclaraciones o dejar de recibir seguimiento, comunícate al','PROJECTCONS will receive only what you send through WhatsApp to respond to your enquiry and discuss your project. For questions or to request that follow-up stop, contact')} <a href="tel:+${config.whatsapp}">${config.phoneDisplay}</a>.</p><h2>${t('Servicios externos','External services')}</h2><p>${t('El alojamiento es GitHub Pages. Las tipografías se cargan desde Google Fonts. Los enlaces de créditos llevan a Pexels. No hemos incorporado herramientas de analítica ni píxeles publicitarios. Esos proveedores pueden procesar datos técnicos al cargar sus recursos o visitar sus enlaces.','Hosting is provided by GitHub Pages. Fonts load from Google Fonts. Photography credit links lead to Pexels. No analytics tools or advertising pixels have been added. These providers may process technical data when their resources load or their links are visited.')}</p><aside class="reference-note"><p>${t('Versión de revisión: el responsable del negocio debe validar y completar su aviso de privacidad definitivo antes del lanzamiento comercial. Este texto describe el funcionamiento actual; no sustituye esa revisión.','Review version: the business owner should validate and complete the final privacy notice before the commercial launch. This text describes current functionality; it does not replace that review.')}</p></aside></div></section>`;
}
function writePage(key, title, description, render, {nav='projects', ready=true, breadcrumb=[]}={}) {
  file=localized(key);
  const content=render();
  const indexable=ready && !config.preview;
  const canonical=url(file);
  const data=[{'@context':'https://schema.org','@type':'WebPage',name:title,url:canonical,inLanguage:lang==='es'?'es-MX':'en',description,isPartOf:{'@id':url('index.html')+'#website'}}];
  if(key==='index.html') data.push({'@context':'https://schema.org','@type':'GeneralContractor','@id':url('index.html')+'#business',name:'PROJECTCONS',url:url('index.html'),telephone:'+'+config.whatsapp,foundingDate:'2008',areaServed:{'@type':'City',name:'La Paz, Baja California Sur, México'},logo:url('assets/images/logo-proyectcons.png'),image:url('assets/images/residencial-01.jpeg')},{'@context':'https://schema.org','@type':'WebSite','@id':url('index.html')+'#website',name:'PROJECTCONS',url:url('index.html'),inLanguage:['es-MX','en']});
  if(breadcrumb.length) data.push({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{name:t('Inicio','Home'),url:localized('index.html')},...breadcrumb.map(item=>({name:item.name,url:localized(item.url)}))].map((item,i)=>({'@type':'ListItem',position:i+1,name:item.name,item:url(item.url)}))});
  const html=`<!doctype html>
<html lang="${lang==='es'?'es-MX':'en'}"><head><meta charset="utf-8">${key==='404.html'?`<base href="${url(lang==='en'?'en/':'')}">`:''}<meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#173c34">
<title>${esc(title)} | PROJECTCONS</title><meta name="description" content="${esc(description)}"><meta name="robots" content="${indexable?'index, follow, max-image-preview:large':'noindex, follow'}"><link rel="canonical" href="${canonical}">
<link rel="alternate" hreflang="es-MX" href="${url(localized(key,'es'))}"><link rel="alternate" hreflang="en" href="${url(localized(key,'en'))}"><link rel="alternate" hreflang="x-default" href="${url(localized(key,'es'))}">
<meta property="og:type" content="website"><meta property="og:site_name" content="PROJECTCONS"><meta property="og:locale" content="${lang==='es'?'es_MX':'en_US'}"><meta property="og:title" content="${esc(title)} | PROJECTCONS"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${url('assets/images/residencial-01.jpeg')}"><meta property="og:image:alt" content="${t('Proyecto residencial de PROJECTCONS','PROJECTCONS residential project')}"><meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="${asset('assets/icons/favicon.svg')}" type="image/svg+xml"><link rel="manifest" href="${asset('site.webmanifest')}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600;650;700&family=Manrope:wght@400;500;600;650;700;750;800&family=Playfair+Display:ital,wght@1,500&display=swap" rel="stylesheet"><link rel="stylesheet" href="${asset('css/styles.css')}"><noscript><style>.nav-toggle{display:none}@media(max-width:1000px){.header-inner{height:auto;min-height:85px;flex-wrap:wrap;padding-block:16px}.site-nav{display:flex;position:static;order:3;width:100%;flex-direction:row;flex-wrap:wrap;padding:0;background:none;border:0}.site-nav a{font-size:13px;width:auto;margin-right:14px}.header-tools{margin-left:auto}}</style></noscript>
${data.map(item=>`<script type="application/ld+json">${JSON.stringify(item).replace(/</g,'\\u003c')}</script>`).join('\n')}</head><body><a class="skip-link" href="#contenido">${t('Saltar al contenido','Skip to content')}</a>${header(nav)}<main id="contenido">${content}</main>${footer()}<script src="${asset('js/config.js')}" defer></script><script src="${asset('js/app.js')}" defer></script>${content.includes('data-gallery')?`<script src="${asset('js/gallery.js')}" defer></script>`:''}</body></html>\n`;
  fs.mkdirSync(path.dirname(path.join(root,file)),{recursive:true});
  fs.writeFileSync(path.join(root,file),html);
  pages.push({file,indexable});
}
for(const language of ['es','en']) {
  lang=language;
  writePage('index.html',t('Constructora en La Paz, BCS · Construye tu proyecto','Construction company in La Paz, BCS · Build your project'),t('PROJECTCONS: constructora en La Paz, Baja California Sur. Más de 18 años de experiencia y más de 60 proyectos. Cuéntanos tu proyecto de vivienda, comercio o bodega.','PROJECTCONS: construction company in La Paz, Baja California Sur. Over 18 years of experience and 60 projects. Tell us about your home, commercial or warehouse project.'),home,{nav:'home'});
  writePage('proyectos.html',t('Proyectos de construcción en La Paz, BCS','Construction projects in La Paz, BCS'),t('Explora proyectos residenciales, locales comerciales, bodegas, casas INFONAVIT y vivienda social. Portafolio de PROJECTCONS en documentación.','Explore residential homes, commercial spaces, warehouses, INFONAVIT homes and affordable housing. The PROJECTCONS portfolio is being documented.'),projectsHub,{breadcrumb:[{name:t('Proyectos','Projects'),url:'proyectos.html'}]});
  writePage('servicios.html',t('Servicios de construcción y proyectos a tu medida en La Paz','Construction services and tailored projects in La Paz'),t('Conoce la propuesta de servicios de PROJECTCONS en La Paz, BCS. Proyectos a tu medida y ejecución de obra. Alcances en revisión.','Explore the proposed PROJECTCONS services in La Paz, BCS. Tailored projects and construction. Final scope under review.'),services,{nav:'services',ready:false,breadcrumb:[{name:t('Servicios','Services'),url:'servicios.html'}]});
  for(const cat of catalog.categories) {
    const projects=Array.from({length:cat.count},(_,i)=>referenceProjects(cat,i,{name:`Proyecto ${String(i+1).padStart(2,'0')}`,description:'',images:[],ready:false,...cat.projects[i]}));
    const categoryFile=`proyectos/${cat.id}/index.html`;
    const crumbList=[{name:t('Proyectos','Projects'),url:'proyectos.html'},{name:catName(cat),url:categoryFile}];
    writePage(categoryFile,`${catName(cat)} ${t('en','in')} La Paz, BCS`,catDescription(cat),()=>categoryPage(cat,projects),{breadcrumb:crumbList});
    projects.forEach((project,i)=>{
      if (new Set(project.images).size<5) throw new Error('Se requieren cinco fotos distintas por galería.');
      if (project.ready && (project.images.length>10 || !project.description?.trim())) throw new Error('Una ficha aprobada requiere descripción y 5–10 fotografías.');
      if (project.ready && project.images.some(img=>visuals.photos[img])) throw new Error('No marcar referencias como portafolio real.');
      const projectFile=`proyectos/${cat.id}/proyecto-${String(i+1).padStart(2,'0')}.html`;
      const name=projectName(project,i);
      writePage(projectFile,`${name} · ${catName(cat)}`,t(`Explora la galería de ${name}. Material de proyecto y referencias identificados. PROJECTCONS, constructora en La Paz, BCS.`,`Explore the ${name} gallery. Project photography and references are clearly identified. PROJECTCONS, construction company in La Paz, BCS.`),()=>detail(cat,project,i),{ready:project.ready,breadcrumb:[...crumbList,{name,url:projectFile}]});
    });
  }
  writePage('privacidad.html',t('Privacidad del formulario de contacto','Contact form privacy'),t('Cómo se utilizan los datos del formulario de PROJECTCONS y cuándo se comparten por WhatsApp.','How the PROJECTCONS form uses your details and when they are shared through WhatsApp.'),privacy,{ready:false,nav:''});
  writePage('404.html',t('No encontramos esta página','Page not found'),t('Vuelve al inicio de PROJECTCONS o explora nuestros proyectos.','Return to the PROJECTCONS home page or explore our projects.'),()=>`<section class="section not-found"><div class="container"><p class="eyebrow">404 / ${t('FUERA DEL PLANO','OFF THE PLAN')}</p><h1>${t('Este espacio<br>no está <em>en el plano.</em>','This space<br>is not <em>on the plan.</em>')}</h1><p>${t('La página pudo cambiar de ubicación. Volvamos al inicio.','The page may have moved. Let’s go back to the start.')}</p>${button(url(localized('index.html')),t('Volver al inicio','Back to home'))}</div></section>`,{ready:false,nav:''});
}
const indexed=pages.filter(page=>page.indexable);
fs.writeFileSync(path.join(root,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${indexed.map(page=>`  <url><loc>${esc(url(page.file))}</loc></url>`).join('\n')}\n</urlset>\n`);
fs.writeFileSync(path.join(root,'robots.txt'),`User-agent: *\nAllow: /\n${config.preview?'# Preview: pages carry noindex until the content is approved.':`Sitemap: ${url('sitemap.xml')}`}\n`);
console.log(`Generated ${pages.length} ES/EN pages. ${indexed.length} indexable. Preview: ${config.preview}.`);
